#!/bin/bash
# DEPLOY_v2_close2 — ترتيب الفائض بأولوية الطبقة (علاج RERANKED_NOT_ADMITTED)
# ثم فحص موجّه ← Smoke ← Full Gate بالتسلسل.  bash DEPLOY_v2_close2.sh
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/v2c2.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/v2c2.b64 > /tmp/v2c2.tgz || { echo "B64_FAIL"; exit 1; }
tar xzf /tmp/v2c2.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
set -a; . /opt/LegalMind/deploy/.env; set +a
nohup /opt/LegalMind/admin/.venv/bin/python \
      /opt/LegalMind/tools/v2_close.py > /tmp/v2close2.log 2>&1 &
disown
echo "بدأ. تابع:  tail -f /tmp/v2close2.log"
